720	func proposalRecords(state *storedState) []ProposalRecord {
721		out := make([]ProposalRecord, 0, len(state.Proposals))
722		for _, p := range state.Proposals {
723			out = append(out, toProposalRecord(p))
724		}
725		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
726		return out
