738	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
739	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
740	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
741		state, err := s.readState()
742		if err != nil {
743			return nil, err
744		}
