794	
795	// ---- 持久化 ----
796	
797	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
798	func (s *Store) loadLocked() (*storedState, error) {
799		raw, err := os.ReadFile(s.path)
800		if err != nil {
801			return nil, err
802		}
803		if len(bytes.TrimSpace(raw)) == 0 {
804			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
805		}
806		// 先于结构扫描与解码逐字节校验字符串：非法 UTF-8 与未配对代理项转义
807		// 会被 encoding/json 悄悄改写成 U+FFFD 且不报错，必须在此明确拒绝，
808		// 使被改写的编号/账户名/动作原文不可能参与后续任何匹配与重放。
809		if err := checkStrictStrings(raw); err != nil {
810			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
811		}
812		if err := checkStateStructure(raw); err != nil {
813			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
814		}
815		var state storedState
816		dec := json.NewDecoder(bytes.NewReader(raw))
817		dec.DisallowUnknownFields()
818		if err := dec.Decode(&state); err != nil {
819			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
820		}
821		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
822		var extra json.RawMessage
823		if err := dec.Decode(&extra); err != io.EOF {
824			if err == nil {
825				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
826			}
827			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
828		}
829		if err := validateState(&state); err != nil {
830			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
831		}
832		return &state, nil
833	}
834	
835	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
836	// 任一步失败都保留上次完整状态。调用方必须持锁。
837	func (s *Store) commitLocked(state *storedState) error {
838		if err := validateState(state); err != nil {
839			return fmt.Errorf("refusing to persist invalid state: %w", err)
840		}
841		payload, err := json.MarshalIndent(state, "", "  ")
842		if err != nil {
843			return err
844		}
845		payload = append(payload, '\n')
846	
847		dir := filepath.Dir(s.path)
848		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
849		if err != nil {
850			return err
851		}
852		tmpName := tmp.Name()
853		cleanup := func() { _ = os.Remove(tmpName) }
854		if _, err := tmp.Write(payload); err != nil {
855			_ = tmp.Close()
856			cleanup()
857			return err
858		}
859		if err := tmp.Sync(); err != nil {
860			_ = tmp.Close()
861			cleanup()
862			return err
863		}
864		if err := tmp.Close(); err != nil {
865			cleanup()
866			return err
867		}
868		if err := os.Chmod(tmpName, 0o600); err != nil {
869			cleanup()
870			return err
871		}
872		if err := os.Rename(tmpName, s.path); err != nil {
873			cleanup()
874			return err
875		}
876		if err := syncDir(dir); err != nil {
877			return err
878		}
879		return nil
880	}
881	
882	func syncDir(dir string) error {
883		d, err := os.Open(dir)
884		if err != nil {
885			return err
886		}
887		defer d.Close()
888		return d.Sync()
889	}
