891	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
892	func validateState(state *storedState) error {
893		if state.Magic != stateMagic {
894			return fmt.Errorf("bad magic %q", state.Magic)
895		}
896		if state.Version != stateVersion {
897			return fmt.Errorf("unsupported state version %d", state.Version)
898		}
899		if state.InitialTreasury < 0 {
900			return errors.New("initial treasury balance is negative")
901		}
902		if state.Treasury < 0 {
903			return errors.New("treasury balance is negative")
904		}
905		if state.Balances == nil {
906			return errors.New("balances table is missing")
907		}
908		if state.Proposals == nil {
909			return errors.New("proposals table is missing")
910		}
911		if state.Receipts == nil {
912			return errors.New("receipts table is missing")
913		}
914		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
915		if state.VoteProposals == nil {
916			state.VoteProposals = map[string]*storedVoteProposal{}
917		}
918		for account, balance := range state.Balances {
919			if account == "" {
920				return errors.New("balance entry with empty account")
921			}
922			if balance < 0 {
923				return fmt.Errorf("balance of %q is negative", account)
924			}
925		}
926		for key, p := range state.Proposals {
927			if p == nil {
928				return fmt.Errorf("proposal %q is empty", key)
929			}
930			if p.ID != key || p.ID == "" {
931				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
932			}
933			if p.State != "passed" && p.State != "executed" {
934				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
935			}
936			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
937		}
938		if err := validateVoteProposals(state); err != nil {
939			return err
940		}
941	
942		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
943		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
944		simTreasury := state.InitialTreasury
945		simBalances := map[string]int64{}
946		seenReceipts := map[string]int{}
947		for order, rcpt := range state.Receipts {
948			if rcpt == nil {
949				return fmt.Errorf("receipt %d is empty", order)
950			}
951			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
952			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
953			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
954			// 编号与字段报损坏，不按数组位置重新编号。
955			if err := validateReceiptOrder(order, rcpt); err != nil {
956				return err
957			}
958			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
959				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
960			}
961			seenReceipts[rcpt.ProposalID] = order
962			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
963			if !found {
964				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
965			}
966			if ownerState != "executed" {
967				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
968			}
969			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
970			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
971			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
972				return err
973			}
974			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
975			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
976			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
977			// 合法记录（第一项动作的 index 0 必须显式保存）。
978			for i := range rcpt.Actions {
979				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
980					return err
981				}
982				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
983					return err
984				}
985			}
986			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
987			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
988			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
989			// 不会被查询或落盘采纳。
990			var verr error
991			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
992			if verr != nil {
993				return verr
994			}
995		}
996		if simTreasury != state.Treasury {
997			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
998		}
999		// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
1000		// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
1001		// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
1002		// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
1003		// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
1004		// 不影响判定。
1005		savedAccounts := make([]string, 0, len(state.Balances))
1006		for account := range state.Balances {
1007			savedAccounts = append(savedAccounts, account)
1008		}
1009		replayAccounts := make([]string, 0, len(simBalances))
1010		for account := range simBalances {
1011			replayAccounts = append(replayAccounts, account)
1012		}
1013		sort.Strings(savedAccounts)
1014		sort.Strings(replayAccounts)
1015		var missing, unexpected []string
1016		si, ri := 0, 0
1017		for si < len(savedAccounts) || ri < len(replayAccounts) {
1018			switch {
1019			case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
1020				unexpected = append(unexpected, savedAccounts[si])
1021				si++
1022			case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
1023				missing = append(missing, replayAccounts[ri])
1024				ri++
1025			default:
1026				si++
1027				ri++
1028			}
1029		}
1030		if len(missing) > 0 || len(unexpected) > 0 {
1031			problems := ""
1032			if len(missing) > 0 {
1033				problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
1034					strings.Join(quoteAccounts(missing), ", "))
1035			}
1036			if len(unexpected) > 0 {
1037				if problems != "" {
1038					problems += "; "
1039				}
1040				problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
1041					strings.Join(quoteAccounts(unexpected), ", "))
1042			}
1043			return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
1044		}
1045		for _, account := range replayAccounts {
1046			if balance := state.Balances[account]; balance != simBalances[account] {
1047				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
1048			}
1049		}
1050		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
1051		for _, p := range state.Proposals {
1052			_, hasReceipt := seenReceipts[p.ID]
1053			if p.State == "executed" && !hasReceipt {
1054				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
1055			}
1056		}
1057		for _, p := range state.VoteProposals {
1058			_, hasReceipt := seenReceipts[p.ID]
1059			if p.State == "executed" && !hasReceipt {
1060				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
1061			}
1062		}
1063		return nil
1064	}
