1066	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1067	func quoteAccounts(accounts []string) []string {
1068		quoted := make([]string, len(accounts))
1069		for i, account := range accounts {
1070			quoted[i] = strconv.Quote(account)
1071		}
1072		return quoted
1073	}
