1075	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
1076	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
1077	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
1078	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
1079	// 位置（0 起），与提案编号一起用于定位。
1080	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
1081	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
1082	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
1083		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
1084			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
1085		}
1086		if rcpt.ExecutedAt < timelockEnd {
1087			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
1088				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
1089		}
1090		return nil
1091	}
