1093	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
1094	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
1095	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
1096	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
1097	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
1098	// position 是凭据在凭据表中的位置（0 起）。
1099	func validateReceiptOrder(position int, rcpt *Receipt) error {
1100		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1101			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1102				position, rcpt.ProposalID, "order", problem)
1103		}
1104		if rcpt.Order != int64(position) {
1105			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1106				position, rcpt.ProposalID, "order", rcpt.Order, position)
1107		}
1108		return nil
1109	}
