1118		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1119			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1120				id, position, "index", problem)
1121		}
1122		if ar.Index != int64(position) {
1123			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1124				id, position, "index", ar.Index, position)
1125		}
1126		return nil
1127	}
