1129	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1130	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1131	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1132	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1133	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1134	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1135	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1136	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1137	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1138		sides := []struct {
1139			name   string
1140			update *BalanceUpdate
1141		}{
1142			{"treasury", &ar.Treasury},
1143			{"recipient", &ar.Recipient},
1144		}
1145		for _, side := range sides {
1146			err := validateRawFields([]rawField{
1147				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1148				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1149			}, func(field, problem string) error {
1150				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1151					id, index, side.name, field, problem)
1152			})
1153			if err != nil {
1154				return err
1155			}
1156		}
1157		return nil
1158	}
