1160	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1161	
1162	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1163	type schemaKind int
1164	
1165	const (
1166		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1167		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1168		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1169		kindArray                     // 数组
1170		kindString                    // 叶子：必须是 JSON 字符串
1171		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1172		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1173	)
1174	
1175	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1176	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1177	type schemaNode struct {
1178		kind   schemaKind
1179		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1180		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1181	}
1182	
1183	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1184	func schemaOf(t reflect.Type) *schemaNode {
1185		for t.Kind() == reflect.Pointer {
1186			t = t.Elem()
1187		}
1188		switch t.Kind() {
1189		case reflect.Struct:
1190			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1191			for i := 0; i < t.NumField(); i++ {
1192				f := t.Field(i)
1193				if f.PkgPath != "" { // 未导出字段不参与 JSON
1194					continue
1195				}
1196				name := f.Name
1197				if tag, ok := f.Tag.Lookup("json"); ok {
1198					tagName, _, _ := strings.Cut(tag, ",")
1199					if tagName == "-" {
1200						continue
1201					}
1202					if tagName != "" {
1203						name = tagName
1204					}
1205				}
1206				node.fields[name] = schemaOf(f.Type)
1207			}
1208			return node
1209		case reflect.Map:
1210			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1211		case reflect.Slice, reflect.Array:
1212			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1213		case reflect.String:
1214			return &schemaNode{kind: kindString}
1215		case reflect.Bool:
1216			return &schemaNode{kind: kindBoolean}
1217		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1218			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1219			return &schemaNode{kind: kindInteger}
1220		default:
1221			return &schemaNode{kind: kindAny}
1222		}
1223	}
1224	
1225	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1226	
1227	func init() {
1228		// 票据的四个标量字段（representative/weight/support/voted_at）由
1229		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1230		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1231		// 不抢在解码器之前用不含票据定位的通用信息报错。
1232		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1233		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1234			ballotFields[name].kind = kindAny
1235		}
1236		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1237		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1238		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1239		// 其“不早于截止”的既有校验不变。
1240		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1241		for _, name := range []string{"for_weight", "against_weight"} {
1242			tallyFields[name].kind = kindAny
1243		}
1244		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1245		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1246		// 叶子位置保持宽松。
1247		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1248		receiptFields["executed_at"].kind = kindAny
1249		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1250		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1251		receiptFields["order"].kind = kindAny
1252		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1253		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1254		// 此叶子位置保持宽松。
1255		receiptFields["actions"].elem.fields["index"].kind = kindAny
1256		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1257		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1258		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1259		actionFields := receiptFields["actions"].elem.fields
1260		for _, side := range []string{"treasury", "recipient"} {
1261			balanceFields := actionFields[side].fields
1262			balanceFields["before"].kind = kindAny
1263			balanceFields["after"].kind = kindAny
1264		}
1265	}
1266	
1267	// scanFrame 是结构扫描的栈帧。
1268	type scanFrame struct {
1269		node    *schemaNode
1270		isArray bool
1271		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1272		seen    map[string]bool
1273		atValue bool // 对象帧：下一个待消费 token 是值而非键
1274		index   int  // 数组帧：下一个元素下标
1275		path    string
1276	}
1277	
1278	func peekFrame(stack []*scanFrame) *scanFrame {
1279		if len(stack) == 0 {
1280			return nil
1281		}
1282		return stack[len(stack)-1]
1283	}
1284	
1285	// checkStateStructure 在解码前逐 token 扫描状态文件：
1286	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1287	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1288	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1289	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1290	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1291	//
1292	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1293	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1294	func checkStateStructure(raw []byte) error {
1295		dec := json.NewDecoder(bytes.NewReader(raw))
1296		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1297		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1298		dec.UseNumber()
1299		var stack []*scanFrame
1300		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1301		pendingNode := storedStateSchema
1302		pendingPath := "state"
1303	
1304		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1305		finishValue := func() {
1306			top := peekFrame(stack)
1307			if top == nil || top.opaque {
1308				return
1309			}
1310			if top.isArray {
1311				top.index++
1312			} else {
1313				top.atValue = false
1314			}
1315		}
1316	
1317		for {
1318			tok, err := dec.Token()
1319			if err == io.EOF {
1320				if len(stack) != 0 {
1321					return errors.New("unterminated object or array")
1322				}
1323				return nil
1324			}
1325			if err != nil {
1326				return err
1327			}
1328	
1329			if top := peekFrame(stack); top != nil && top.opaque {
1330				// 不透明容器内不做字段检查，只配对括号。
1331				if d, ok := tok.(json.Delim); ok {
1332					if d == '{' || d == '[' {
1333						stack = append(stack, &scanFrame{opaque: true})
1334					} else {
1335						stack = stack[:len(stack)-1]
1336						finishValue()
1337					}
1338				}
1339				continue
1340			}
1341	
1342			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1343				// 对象帧的键位置：闭括号或下一个键。
1344				if d, ok := tok.(json.Delim); ok {
1345					if d != '}' {
1346						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1347					}
1348					stack = stack[:len(stack)-1]
1349					finishValue()
1350					continue
1351				}
1352				key, ok := tok.(string)
1353				if !ok {
1354					return errors.New("object key must be a string")
1355				}
1356				if top.seen[key] {
1357					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1358				}
1359				top.seen[key] = true
1360				top.atValue = true
1361				switch top.node.kind {
1362				case kindObject:
1363					child, known := top.node.fields[key]
1364					if !known {
1365						return fmt.Errorf("unknown field %q at %s", key, top.path)
1366					}
1367					pendingNode = child
1368					pendingPath = top.path + "." + key
1369				case kindMap:
1370					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1371					pendingNode = top.node.elem
1372					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1373				}
1374				continue
1375			}
1376	
1377			// 值位置：对象键之后的值或数组元素。
1378			node := pendingNode
1379			path := pendingPath
1380			if top := peekFrame(stack); top != nil && top.isArray {
1381				node = top.node.elem
1382				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1383			}
1384			if d, ok := tok.(json.Delim); ok {
1385				switch d {
1386				case '{', '[':
1387					frame := &scanFrame{isArray: d == '[', path: path}
1388					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1389						(d == '[' && node.kind == kindArray)
1390					if !shapeOK {
1391						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1392						frame.opaque = true
1393					} else {
1394						frame.node = node
1395						if d == '{' {
1396							frame.seen = map[string]bool{}
1397						}
1398					}
1399					stack = append(stack, frame)
1400				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1401					if len(stack) == 0 {
1402						return errors.New("unexpected closing delimiter")
1403					}
1404					stack = stack[:len(stack)-1]
1405					finishValue()
1406				}
1407				continue
1408			}
1409			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1410			// null 不允许用来顶替字符串/布尔/整数。
1411			if err := checkLeafScalar(node, path, tok); err != nil {
1412				return err
1413			}
1414			finishValue()
1415		}
1416	}
1417	
1418	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1419	func leafKindName(k schemaKind) string {
1420		switch k {
1421		case kindString:
1422			return "string"
1423		case kindBoolean:
1424			return "boolean"
1425		case kindInteger:
1426			return "integer"
1427		default:
1428			return "value"
1429		}
1430	}
1431	
1432	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1433	func tokenKindName(tok json.Token) string {
1434		switch v := tok.(type) {
1435		case nil:
1436			return "null"
1437		case string:
1438			return "string"
1439		case bool:
1440			return "boolean"
1441		case json.Number:
1442			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1443				return "integer"
1444			}
1445			return "number"
1446		default:
1447			return "value"
1448		}
1449	}
1450	
1451	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1452	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1453	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1454		switch node.kind {
1455		case kindString, kindBoolean, kindInteger:
1456		default:
1457			return nil
1458		}
1459		if node.kind == kindInteger {
1460			if n, ok := tok.(json.Number); ok {
1461				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1462					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1463				}
1464				return nil
1465			}
1466		}
1467		want := leafKindName(node.kind)
1468		if got := tokenKindName(tok); got != want {
1469			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1470		}
1471		return nil
1472	}
1473

