package govflow

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
)

// 资金库状态文件相关错误。
var (
	// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
	ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
	// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
	ErrStateCorrupt = errors.New("treasury state file is corrupt")
	// ErrProposalNotFound：按编号查询或执行时提案不存在。
	ErrProposalNotFound = errors.New("proposal not found")
	// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
	ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
	// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
	ErrInvalidRegistration = errors.New("invalid registration")
)

const (
	stateMagic   = "govflow-treasury-state"
	stateVersion = 1
	lockSuffix   = ".lock"
)

// BalanceUpdate 记录一个账户在一次动作前后的余额。
//
// before 与 after 必须各自明确写出且为 int64 整数：字段缺失、为 null 或
// 类型不符都不得被折叠成 0 再当作合法凭据读出——某个余额本来应为 0 时，
// 缺失字段与明确写出的 0 在解码后必须仍可区分。因此解码时保留字段的原始
// JSON，由 validateReceiptActionBalances 区分“缺失/空值/类型不符”。
type BalanceUpdate struct {
	Account string `json:"account"`
	Before  int64  `json:"before"`
	After   int64  `json:"after"`

	beforeRaw json.RawMessage
	afterRaw  json.RawMessage
}

// balanceUpdateJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
type balanceUpdateJSONShape struct {
	Account string          `json:"account"`
	Before  json.RawMessage `json:"before"`
	After   json.RawMessage `json:"after"`
}

// UnmarshalJSON 保留 before/after 是否出现及其原始写法（缺失为 nil、null 为
// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给
// validateReceiptActionBalances，此处只在字段确实是 int64 整数时填充值。
func (u *BalanceUpdate) UnmarshalJSON(data []byte) error {
	var shape balanceUpdateJSONShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return err
	}
	u.Account = shape.Account
	u.beforeRaw, u.afterRaw = shape.Before, shape.After
	fillInt64(shape.Before, &u.Before)
	fillInt64(shape.After, &u.After)
	return nil
}

// mustBalanceUpdate 构造一份内存中的合法余额记录（首次执行构造凭据使用）。
// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
// validateReceiptActionBalances 判定时不会把本进程新建的凭据误判为字段缺失。
func mustBalanceUpdate(account string, before, after int64) BalanceUpdate {
	beforeRaw, _ := json.Marshal(before)
	afterRaw, _ := json.Marshal(after)
	return BalanceUpdate{
		Account: account, Before: before, After: after,
		beforeRaw: beforeRaw, afterRaw: afterRaw,
	}
}

// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
// 以及该动作引发的资金库与收款账户余额变动。两侧的 before/after 四个余额字段
// 都必须明确写出；任何一个缺失、为 null 或类型不符，整份状态文件即判损坏，
// 不能根据转账金额、账户余额或其它凭据补出（见 validateReceiptActionBalances）。
//
// index 同样必须明确写出：它是执行留痕的一部分，记录恰好排在 actions 第一项
// 并不能补出一个合法的 0。字段缺失、为 null、不是 int64 范围内的非负整数
// （字符串/布尔/小数/指数/超界/负数）或与该动作在凭据中的实际位置不符，都判
// 整份状态损坏（见 validateReceiptActionIndex）。因此解码时保留 index 的原始
// JSON，与余额字段走同一套“缺失/空值/类型不符”判定。
type ActionReceipt struct {
	Index     int64         `json:"index"`
	Action    string        `json:"action"`
	Treasury  BalanceUpdate `json:"treasury"`
	Recipient BalanceUpdate `json:"recipient"`

	indexRaw json.RawMessage
}

// actionReceiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
type actionReceiptJSONShape struct {
	Index     json.RawMessage `json:"index"`
	Action    string          `json:"action"`
	Treasury  BalanceUpdate   `json:"treasury"`
	Recipient BalanceUpdate   `json:"recipient"`
}

// UnmarshalJSON 保留 index 是否出现及其原始写法（缺失为 nil、null 为 "null"），
// 使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接解进 int64
// 会把缺失/null/类型不符都折叠成 0，第一项动作缺失 index 时就会被误当成合法
// 编号 0。判定统一交给 validateReceiptActionIndex，此处只在字段确实是 int64
// 整数时填充值。
func (a *ActionReceipt) UnmarshalJSON(data []byte) error {
	var shape actionReceiptJSONShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return err
	}
	a.Action = shape.Action
	a.Treasury = shape.Treasury
	a.Recipient = shape.Recipient
	a.indexRaw = shape.Index
	fillInt64(shape.Index, &a.Index)
	return nil
}

// Receipt 是一项提案首次成功执行后生成的执行凭据。
// 一项提案只允许成功一次；重试返回同一份凭据。
//
// executed_at 必须明确写出且不得早于对应提案的 timelock_end：首次执行只在
// now 达到时间锁后发生，保存的凭据必须满足同一条执行资格规则。字段缺失、
// 为 null 或类型不符都不得被折叠成 0 再当作合法凭据读出，因此解码时保留
// 字段的原始 JSON，由 validateState 区分“缺失/空值/类型不符/早于时间锁”。
type Receipt struct {
	ProposalID string          `json:"proposal_id"`
	ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
	Order      int64           `json:"order"`       // 成功提交的先后顺序，0 起
	Actions    []ActionReceipt `json:"actions"`

	executedAtRaw json.RawMessage
	orderRaw      json.RawMessage
}

// receiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
type receiptJSONShape struct {
	ProposalID string          `json:"proposal_id"`
	ExecutedAt json.RawMessage `json:"executed_at"`
	Order      json.RawMessage `json:"order"`
	Actions    []ActionReceipt `json:"actions"`
}

// UnmarshalJSON 保留 executed_at/order 是否出现及其原始写法（缺失为 nil、null 为
// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
// 解进 int64 会把缺失/null/类型不符都折叠成 0，第一份凭据缺失 order 时就会被
// 误当成合法编号 0。判定统一交给 validateState，此处只在字段确实是 int64
// 整数时填充 ExecutedAt/Order。
func (r *Receipt) UnmarshalJSON(data []byte) error {
	var shape receiptJSONShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return err
	}
	r.ProposalID = shape.ProposalID
	r.Actions = shape.Actions
	r.executedAtRaw = shape.ExecutedAt
	r.orderRaw = shape.Order
	fillInt64(shape.ExecutedAt, &r.ExecutedAt)
	fillInt64(shape.Order, &r.Order)
	return nil
}

// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
type ProposalRecord struct {
	ID          string   `json:"id"`
	State       string   `json:"state"`
	TimelockEnd int64    `json:"timelock_end"`
	Actions     []string `json:"actions"`
}

// ---- 磁盘结构（JSON） ----

type storedProposal struct {
	ID          string   `json:"id"`
	State       string   `json:"state"`
	TimelockEnd int64    `json:"timelock_end"`
	Actions     []string `json:"actions"`
}

type storedState struct {
	Magic           string                         `json:"magic"`
	Version         int                            `json:"version"`
	InitialTreasury int64                          `json:"initial_treasury"`
	Treasury        int64                          `json:"treasury"`
	Balances        map[string]int64               `json:"balances"`
	Proposals       map[string]*storedProposal     `json:"proposals"`
	Receipts        []*Receipt                     `json:"receipts"`
	VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
}

// Store 是绑定到单个本地状态文件的资金库句柄。
// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
// 通过进程内互斥锁与文件锁（flock）串行化。
type Store struct {
	path   string
	mu     sync.Mutex // 保护本句柄上的全部操作
	lockFD *os.File   // 跨进程文件锁
	closed bool
}

// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
var (
	pathLocksMu sync.Mutex
	pathLocks   = map[string]*sync.Mutex{}
)

// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
func canonicalPath(path string) (string, error) {
	return filepath.Abs(path)
}

func inProcessLock(path string) *sync.Mutex {
	pathLocksMu.Lock()
	defer pathLocksMu.Unlock()
	m, ok := pathLocks[path]
	if !ok {
		m = &sync.Mutex{}
		pathLocks[path] = m
	}
	return m
}

// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
// treasury 必须落在有符号 64 位整数范围内且不得为负。
func InitTreasury(path string, treasury int64) (*Store, error) {
	if treasury < 0 {
		return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
	}
	path, err := canonicalPath(path)
	if err != nil {
		return nil, err
	}
	pathMu := inProcessLock(path)
	pathMu.Lock()
	defer pathMu.Unlock()

	// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
	// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
	lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
		_ = lockFD.Close()
		return nil, err
	}
	// O_EXCL 保证与并发初始化竞争时只有一方成功。
	fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
		_ = lockFD.Close()
		if errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
		}
		return nil, err
	}
	_ = fd.Close()

	store := &Store{path: path, lockFD: lockFD}
	if err := store.commitLocked(newStoredState(treasury)); err != nil {
		_ = store.funlock()
		_ = lockFD.Close()
		_ = os.Remove(path)
		return nil, err
	}
	// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
	if err := store.funlock(); err != nil {
		_ = lockFD.Close()
		_ = os.Remove(path)
		return nil, err
	}
	return store, nil
}

// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
func Open(path string) (*Store, error) {
	path, err := canonicalPath(path)
	if err != nil {
		return nil, err
	}
	pathMu := inProcessLock(path)
	pathMu.Lock()
	defer pathMu.Unlock()
	return openStoreHoldingPathLock(path)
}

// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
func openStoreHoldingPathLock(path string) (*Store, error) {
	if _, err := os.Stat(path); err != nil {
		return nil, err
	}
	lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
		_ = lockFD.Close()
		return nil, err
	}
	store := &Store{path: path, lockFD: lockFD}
	if _, err := store.loadLocked(); err != nil {
		_ = store.funlock()
		_ = lockFD.Close()
		return nil, err
	}
	// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
	if err := store.funlock(); err != nil {
		_ = lockFD.Close()
		return nil, err
	}
	return store, nil
}

// Path 返回状态文件路径。
func (s *Store) Path() string { return s.path }

// Close 释放文件锁。关闭后其它操作返回错误。
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil
	}
	s.closed = true
	if err := s.funlock(); err != nil {
		_ = s.lockFD.Close()
		return err
	}
	return s.lockFD.Close()
}

func (s *Store) flock(how int) error {
	if s.lockFD == nil {
		return errors.New("treasury store is closed")
	}
	return syscall.Flock(int(s.lockFD.Fd()), how)
}

func (s *Store) funlock() error {
	if s.lockFD == nil {
		return nil
	}
	return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
}

// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
// 返回的 commit 在操作结束时释放锁。
func (s *Store) begin() (func(), error) {
	pathMu := inProcessLock(s.path)
	pathMu.Lock()
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		pathMu.Unlock()
		return nil, errors.New("treasury store is closed")
	}
	if err := s.flock(syscall.LOCK_EX); err != nil {
		s.mu.Unlock()
		pathMu.Unlock()
		return nil, err
	}
	return func() {
		_ = s.funlock()
		s.mu.Unlock()
		pathMu.Unlock()
	}, nil
}

func newStoredState(treasury int64) *storedState {
	return &storedState{
		Magic:           stateMagic,
		Version:         stateVersion,
		InitialTreasury: treasury,
		Treasury:        treasury,
		Balances:        map[string]int64{},
		Proposals:       map[string]*storedProposal{},
		Receipts:        []*Receipt{},
		VoteProposals:   map[string]*storedVoteProposal{},
	}
}

// ---- 登记 ----

// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
// 内容不同则返回 ErrProposalConflict。
// 需要这次登记实际认可的完整记录（含已执行提案的实际状态）时使用
// RegisterProposal；两者走同一条登记路径，重试标志含义一致。
//
// 提案编号与每一项动作原文还必须是合法 UTF-8：状态文件以 JSON 保存，
// encoding/json 会把字符串中的非法 UTF-8 字节悄悄改写成替换字符 U+FFFD
// 且不报错。登记入口若放行，落盘的编号/动作原文就不再是用户提交的原文——
// 原编号无法查询，收款账户名称与原文不同。因此这两类文本在一切落盘之前
// 逐字校验，非法输入整项登记失败（ErrInvalidRegistration），不新增提案、
// 不保存部分动作；错误说明是编号还是动作原文，动作出错时指出它在提交
// 列表中的位置（0 起）。即使非法输入改写后恰好等于状态中已存在的合法
// 编号（如含真实 U+FFFD 的编号），也不被当作该编号的成功重试或内容冲突。
// 合法文本（含中文、表情、用户明确写出的 U+FFFD，以及 "\uD800" 这类
// 由反斜杠与普通字母组成的字面文本——登记参数不是 JSON 字符串，不做
// 转义重解释）原样保留。编码合法但转账格式错误的动作照常登记，
// 由执行操作按现有规则拒绝。
func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
	_, existed, err = s.RegisterProposal(id, timelockEnd, actions)
	return existed, err
}

// RegisterProposal 与 Register 执行同一登记流程，并额外返回这次登记实际认可的
// 完整记录，使调用方能区分三种成功结果：
//   - 首次登记：existed=false，记录状态为 passed；
//   - 相同内容重试且提案尚未执行：existed=true，记录状态为 passed；
//   - 相同内容重试且提案已执行：existed=true，记录状态为 executed。
//
// 返回记录的编号、时间锁、动作原文及动作顺序就是这次登记认可的那一条记录：
// 相同内容重试只确认已有提案，不改写状态、余额或首次执行凭据。若登记重试与
// 首次执行同时发生，两者由文件锁串行化，响应按实际确认的先后反映状态——
// 登记先确认时返回 passed，执行先完成时返回 executed；记录是本次确认时的
// 副本，随后执行完成不会改写已返回的结果。
func (s *Store) RegisterProposal(id string, timelockEnd int64, actions []string) (ProposalRecord, bool, error) {
	if id == "" {
		return ProposalRecord{}, false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
	}
	if problem := invalidUTF8(id); problem != "" {
		return ProposalRecord{}, false, fmt.Errorf("%w: proposal id is not valid UTF-8: %s", ErrInvalidRegistration, problem)
	}
	for i, action := range actions {
		if problem := invalidUTF8(action); problem != "" {
			return ProposalRecord{}, false, fmt.Errorf("%w: action %d text is not valid UTF-8: %s", ErrInvalidRegistration, i, problem)
		}
	}
	commit, err := s.begin()
	if err != nil {
		return ProposalRecord{}, false, err
	}
	defer commit()

	state, err := s.loadLocked()
	if err != nil {
		return ProposalRecord{}, false, err
	}
	stored := copyActions(actions)
	if existing, ok := state.Proposals[id]; ok {
		if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
			// 相同内容重试：只确认已有记录，按本次持锁读取时的实际状态
			// （passed 或 executed）返回副本；不提交、不改写任何状态。
			return toProposalRecord(existing), true, nil
		}
		return ProposalRecord{}, false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
	}
	// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
	if vp, ok := state.VoteProposals[id]; ok {
		return ProposalRecord{}, false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
	}
	fresh := &storedProposal{
		ID:          id,
		State:       "passed",
		TimelockEnd: timelockEnd,
		Actions:     stored,
	}
	state.Proposals[id] = fresh
	if err := s.commitLocked(state); err != nil {
		return ProposalRecord{}, false, err
	}
	return toProposalRecord(fresh), false, nil
}

func copyActions(actions []string) []string {
	if actions == nil {
		return nil
	}
	copied := make([]string, len(actions))
	copy(copied, actions)
	return copied
}

// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
func sameActions(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// ---- 执行 ----

// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
type executionTarget struct {
	state        string
	timelockEnd  int64
	actions      []string
	markExecuted func()
}

// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
func resolveExecutable(state *storedState, id string) *executionTarget {
	if p, ok := state.Proposals[id]; ok {
		return &executionTarget{
			state:        p.State,
			timelockEnd:  p.TimelockEnd,
			actions:      p.Actions,
			markExecuted: func() { p.State = "executed" },
		}
	}
	if vp, ok := state.VoteProposals[id]; ok {
		return &executionTarget{
			state:        vp.State,
			timelockEnd:  vp.TimelockEnd,
			actions:      vp.Actions,
			markExecuted: func() { vp.State = "executed" },
		}
	}
	return nil
}

// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
	if p, ok := state.Proposals[id]; ok {
		return p.State, p.TimelockEnd, p.Actions, true
	}
	if vp, ok := state.VoteProposals[id]; ok {
		return vp.State, vp.TimelockEnd, vp.Actions, true
	}
	return "", 0, nil, false
}

// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
func (s *Store) Execute(id string, now int64) (*Receipt, error) {
	commit, err := s.begin()
	if err != nil {
		return nil, err
	}
	defer commit()

	state, err := s.loadLocked()
	if err != nil {
		return nil, err
	}
	target := resolveExecutable(state, id)
	if target == nil {
		return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
	}
	if target.state == "executed" {
		if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
			return cloneReceipt(rcpt), nil
		}
		return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
	}
	if target.state != "passed" {
		return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
	}
	if now < target.timelockEnd {
		return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
	}
	if len(target.actions) == 0 {
		return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
	}

	// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
	// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
	steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
	if perr != nil {
		return nil, perr
	}

	// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
	receipt := &Receipt{
		ProposalID: id,
		ExecutedAt: now,
		Order:      int64(len(state.Receipts)),
		Actions:    make([]ActionReceipt, 0, len(steps)),
	}
	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
	// executed_at/order 判定时不会把本进程新建的凭据误判为字段缺失。
	receipt.executedAtRaw, _ = json.Marshal(now)
	receipt.orderRaw, _ = json.Marshal(receipt.Order)
	for i, st := range steps {
		receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
	}
	state.Treasury = simTreasury
	state.Balances = simBalances
	target.markExecuted()
	state.Receipts = append(state.Receipts, receipt)

	if err := s.commitLocked(state); err != nil {
		return nil, err
	}
	return cloneReceipt(receipt), nil
}

func findReceipt(receipts []*Receipt, id string) *Receipt {
	for _, r := range receipts {
		if r.ProposalID == id {
			return r
		}
	}
	return nil
}

func cloneReceipt(r *Receipt) *Receipt {
	if r == nil {
		return nil
	}
	copied := *r
	if r.Actions != nil {
		copied.Actions = make([]ActionReceipt, len(r.Actions))
		copy(copied.Actions, r.Actions)
	}
	return &copied
}

// ---- 查询 ----

// BalanceSnapshot 是同一份完整已提交状态下的资金库余额与全部收款账户余额。
// 一次 BalanceSnapshot 调用只读取一次状态文件，保证返回的字段彼此一致：
// 不会把不同提交时刻的余额拼在一起。
type BalanceSnapshot struct {
	Treasury int64            `json:"treasury"`
	Balances map[string]int64 `json:"balances"`
}

// BalanceSnapshot 在一次持锁读取中取得资金库与全部收款账户余额。
// 返回的 Balances 是副本（永不为 nil），调用方可自由使用；
// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
func (s *Store) BalanceSnapshot() (*BalanceSnapshot, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	out := &BalanceSnapshot{
		Treasury: state.Treasury,
		Balances: make(map[string]int64, len(state.Balances)),
	}
	for k, v := range state.Balances {
		out.Balances[k] = v
	}
	return out, nil
}

// TreasuryBalance 返回资金库当前余额。
func (s *Store) TreasuryBalance() (int64, error) {
	state, err := s.readState()
	if err != nil {
		return 0, err
	}
	return state.Treasury, nil
}

// Balance 返回收款账户余额；从未出现过的账户余额为零。
func (s *Store) Balance(account string) (int64, error) {
	state, err := s.readState()
	if err != nil {
		return 0, err
	}
	return state.Balances[account], nil
}

// Balances 返回全部出现过的收款账户余额的副本，按账户名排序。
func (s *Store) Balances() (map[string]int64, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	out := make(map[string]int64, len(state.Balances))
	for k, v := range state.Balances {
		out[k] = v
	}
	return out, nil
}

// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
	state, err := s.readState()
	if err != nil {
		return ProposalRecord{}, false, err
	}
	p, ok := state.Proposals[id]
	if !ok {
		return ProposalRecord{}, false, nil
	}
	return toProposalRecord(p), true, nil
}

// Proposals 返回全部已登记提案，按编号排序。
func (s *Store) Proposals() ([]ProposalRecord, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	return proposalRecords(state), nil
}

func proposalRecords(state *storedState) []ProposalRecord {
	out := make([]ProposalRecord, 0, len(state.Proposals))
	for _, p := range state.Proposals {
		out = append(out, toProposalRecord(p))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// ProposalsSnapshot 是同一份完整已提交状态下的登记提案与投票提案列表。
// 一次 ProposalsSnapshot 调用只读取一次状态文件，保证两个来源的提案状态、
// 动作与投票明细彼此一致：不会把不同提交时刻的提案状态拼在一起。
type ProposalsSnapshot struct {
	Registered []ProposalRecord    `json:"registered"`
	Voting     []*VoteProposalView `json:"voting"`
}

// ProposalsSnapshot 在一次持锁读取中取得全部登记提案与全部投票提案。
// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	return &ProposalsSnapshot{
		Registered: proposalRecords(state),
		Voting:     voteProposalViews(state),
	}, nil
}

func toProposalRecord(p *storedProposal) ProposalRecord {
	return ProposalRecord{
		ID:          p.ID,
		State:       p.State,
		TimelockEnd: p.TimelockEnd,
		Actions:     copyActions(p.Actions),
	}
}

// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
func (s *Store) Receipt(id string) (*Receipt, bool, error) {
	state, err := s.readState()
	if err != nil {
		return nil, false, err
	}
	r := findReceipt(state.Receipts, id)
	if r == nil {
		return nil, false, nil
	}
	return cloneReceipt(r), true, nil
}

// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
func (s *Store) Receipts() ([]*Receipt, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	out := make([]*Receipt, 0, len(state.Receipts))
	for _, r := range state.Receipts {
		out = append(out, cloneReceipt(r))
	}
	return out, nil
}

func (s *Store) readState() (*storedState, error) {
	commit, err := s.begin()
	if err != nil {
		return nil, err
	}
	defer commit()
	return s.loadLocked()
}

// ---- 持久化 ----

// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
func (s *Store) loadLocked() (*storedState, error) {
	raw, err := os.ReadFile(s.path)
	if err != nil {
		return nil, err
	}
	if len(bytes.TrimSpace(raw)) == 0 {
		return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
	}
	// 先于结构扫描与解码逐字节校验字符串：非法 UTF-8 与未配对代理项转义
	// 会被 encoding/json 悄悄改写成 U+FFFD 且不报错，必须在此明确拒绝，
	// 使被改写的编号/账户名/动作原文不可能参与后续任何匹配与重放。
	if err := checkStrictStrings(raw); err != nil {
		return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
	}
	if err := checkStateStructure(raw); err != nil {
		return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
	}
	var state storedState
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
	}
	// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
		}
		return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
	}
	if err := validateState(&state); err != nil {
		return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
	}
	return &state, nil
}

// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
// 任一步失败都保留上次完整状态。调用方必须持锁。
func (s *Store) commitLocked(state *storedState) error {
	if err := validateState(state); err != nil {
		return fmt.Errorf("refusing to persist invalid state: %w", err)
	}
	payload, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	payload = append(payload, '\n')

	dir := filepath.Dir(s.path)
	tmp, err := os.CreateTemp(dir, ".govflow-state-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	cleanup := func() { _ = os.Remove(tmpName) }
	if _, err := tmp.Write(payload); err != nil {
		_ = tmp.Close()
		cleanup()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		cleanup()
		return err
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return err
	}
	if err := os.Chmod(tmpName, 0o600); err != nil {
		cleanup()
		return err
	}
	if err := os.Rename(tmpName, s.path); err != nil {
		cleanup()
		return err
	}
	if err := syncDir(dir); err != nil {
		return err
	}
	return nil
}

func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}

// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
func validateState(state *storedState) error {
	if state.Magic != stateMagic {
		return fmt.Errorf("bad magic %q", state.Magic)
	}
	if state.Version != stateVersion {
		return fmt.Errorf("unsupported state version %d", state.Version)
	}
	if state.InitialTreasury < 0 {
		return errors.New("initial treasury balance is negative")
	}
	if state.Treasury < 0 {
		return errors.New("treasury balance is negative")
	}
	if state.Balances == nil {
		return errors.New("balances table is missing")
	}
	if state.Proposals == nil {
		return errors.New("proposals table is missing")
	}
	if state.Receipts == nil {
		return errors.New("receipts table is missing")
	}
	// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
	if state.VoteProposals == nil {
		state.VoteProposals = map[string]*storedVoteProposal{}
	}
	for account, balance := range state.Balances {
		if account == "" {
			return errors.New("balance entry with empty account")
		}
		if balance < 0 {
			return fmt.Errorf("balance of %q is negative", account)
		}
	}
	for key, p := range state.Proposals {
		if p == nil {
			return fmt.Errorf("proposal %q is empty", key)
		}
		if p.ID != key || p.ID == "" {
			return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
		}
		if p.State != "passed" && p.State != "executed" {
			return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
		}
		// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
	}
	if err := validateVoteProposals(state); err != nil {
		return err
	}

	// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
	// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
	simTreasury := state.InitialTreasury
	simBalances := map[string]int64{}
	seenReceipts := map[string]int{}
	for order, rcpt := range state.Receipts {
		if rcpt == nil {
			return fmt.Errorf("receipt %d is empty", order)
		}
		// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
		// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
		// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
		// 编号与字段报损坏，不按数组位置重新编号。
		if err := validateReceiptOrder(order, rcpt); err != nil {
			return err
		}
		if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
			return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
		}
		seenReceipts[rcpt.ProposalID] = order
		ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
		if !found {
			return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
		}
		if ownerState != "executed" {
			return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
		}
		// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
		// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
		if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
			return err
		}
		// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
		// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
		// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
		// 合法记录（第一项动作的 index 0 必须显式保存）。
		for i := range rcpt.Actions {
			if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
				return err
			}
			if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
				return err
			}
		}
		// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
		// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
		// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
		// 不会被查询或落盘采纳。
		var verr error
		simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
		if verr != nil {
			return verr
		}
	}
	if simTreasury != state.Treasury {
		return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
	}
	// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
	// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
	// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
	// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
	// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
	// 不影响判定。
	savedAccounts := make([]string, 0, len(state.Balances))
	for account := range state.Balances {
		savedAccounts = append(savedAccounts, account)
	}
	replayAccounts := make([]string, 0, len(simBalances))
	for account := range simBalances {
		replayAccounts = append(replayAccounts, account)
	}
	sort.Strings(savedAccounts)
	sort.Strings(replayAccounts)
	var missing, unexpected []string
	si, ri := 0, 0
	for si < len(savedAccounts) || ri < len(replayAccounts) {
		switch {
		case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
			unexpected = append(unexpected, savedAccounts[si])
			si++
		case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
			missing = append(missing, replayAccounts[ri])
			ri++
		default:
			si++
			ri++
		}
	}
	if len(missing) > 0 || len(unexpected) > 0 {
		problems := ""
		if len(missing) > 0 {
			problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
				strings.Join(quoteAccounts(missing), ", "))
		}
		if len(unexpected) > 0 {
			if problems != "" {
				problems += "; "
			}
			problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
				strings.Join(quoteAccounts(unexpected), ", "))
		}
		return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
	}
	for _, account := range replayAccounts {
		if balance := state.Balances[account]; balance != simBalances[account] {
			return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
		}
	}
	// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
	for _, p := range state.Proposals {
		_, hasReceipt := seenReceipts[p.ID]
		if p.State == "executed" && !hasReceipt {
			return fmt.Errorf("proposal %q is executed without receipt", p.ID)
		}
	}
	for _, p := range state.VoteProposals {
		_, hasReceipt := seenReceipts[p.ID]
		if p.State == "executed" && !hasReceipt {
			return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
		}
	}
	return nil
}

// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
func quoteAccounts(accounts []string) []string {
	quoted := make([]string, len(accounts))
	for i, account := range accounts {
		quoted[i] = strconv.Quote(account)
	}
	return quoted
}

// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
// 位置（0 起），与提案编号一起用于定位。
// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
	if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
		return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
	}
	if rcpt.ExecutedAt < timelockEnd {
		return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
			order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
	}
	return nil
}

// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
// position 是凭据在凭据表中的位置（0 起）。
func validateReceiptOrder(position int, rcpt *Receipt) error {
	if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
		return fmt.Errorf("receipt %d for proposal %q field %q %s",
			position, rcpt.ProposalID, "order", problem)
	}
	if rcpt.Order != int64(position) {
		return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
			position, rcpt.ProposalID, "order", rcpt.Order, position)
	}
	return nil
}

// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
// 动作在凭据 actions 中的位置（0 起）。
func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
	if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
		return fmt.Errorf("receipt for proposal %q action %d field %q %s",
			id, position, "index", problem)
	}
	if ar.Index != int64(position) {
		return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
			id, position, "index", ar.Index, position)
	}
	return nil
}

// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
	sides := []struct {
		name   string
		update *BalanceUpdate
	}{
		{"treasury", &ar.Treasury},
		{"recipient", &ar.Recipient},
	}
	for _, side := range sides {
		err := validateRawFields([]rawField{
			{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
			{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
		}, func(field, problem string) error {
			return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
				id, index, side.name, field, problem)
		})
		if err != nil {
			return err
		}
	}
	return nil
}

// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----

// schemaKind 是状态文件 JSON 在某一层的形状类别。
type schemaKind int

const (
	kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
	kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
	kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
	kindArray                     // 数组
	kindString                    // 叶子：必须是 JSON 字符串
	kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
	kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
)

// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
type schemaNode struct {
	kind   schemaKind
	fields map[string]*schemaNode // kindObject：字段名 → 值的形状
	elem   *schemaNode            // kindMap/kindArray：值/元素的形状
}

// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
func schemaOf(t reflect.Type) *schemaNode {
	for t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	switch t.Kind() {
	case reflect.Struct:
		node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			if f.PkgPath != "" { // 未导出字段不参与 JSON
				continue
			}
			name := f.Name
			if tag, ok := f.Tag.Lookup("json"); ok {
				tagName, _, _ := strings.Cut(tag, ",")
				if tagName == "-" {
					continue
				}
				if tagName != "" {
					name = tagName
				}
			}
			node.fields[name] = schemaOf(f.Type)
		}
		return node
	case reflect.Map:
		return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
	case reflect.Slice, reflect.Array:
		return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
	case reflect.String:
		return &schemaNode{kind: kindString}
	case reflect.Bool:
		return &schemaNode{kind: kindBoolean}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return &schemaNode{kind: kindInteger}
	default:
		return &schemaNode{kind: kindAny}
	}
}

var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))

func init() {
	// 票据的四个标量字段（representative/weight/support/voted_at）由
	// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
	// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
	// 不抢在解码器之前用不含票据定位的通用信息报错。
	ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
	for _, name := range []string{"representative", "weight", "support", "voted_at"} {
		ballotFields[name].kind = kindAny
	}
	// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
	// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
	// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
	// 其“不早于截止”的既有校验不变。
	tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
	for _, name := range []string{"for_weight", "against_weight"} {
		tallyFields[name].kind = kindAny
	}
	// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
	// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
	// 叶子位置保持宽松。
	receiptFields := storedStateSchema.fields["receipts"].elem.fields
	receiptFields["executed_at"].kind = kindAny
	// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
	// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
	receiptFields["order"].kind = kindAny
	// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
	// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
	// 此叶子位置保持宽松。
	receiptFields["actions"].elem.fields["index"].kind = kindAny
	// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
	// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
	// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
	actionFields := receiptFields["actions"].elem.fields
	for _, side := range []string{"treasury", "recipient"} {
		balanceFields := actionFields[side].fields
		balanceFields["before"].kind = kindAny
		balanceFields["after"].kind = kindAny
	}
}

// scanFrame 是结构扫描的栈帧。
type scanFrame struct {
	node    *schemaNode
	isArray bool
	opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
	seen    map[string]bool
	atValue bool // 对象帧：下一个待消费 token 是值而非键
	index   int  // 数组帧：下一个元素下标
	path    string
}

func peekFrame(stack []*scanFrame) *scanFrame {
	if len(stack) == 0 {
		return nil
	}
	return stack[len(stack)-1]
}

// checkStateStructure 在解码前逐 token 扫描状态文件：
//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
//
// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
// 便于定位。字段顺序、缩进与合法转义不影响判定。
func checkStateStructure(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
	// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
	dec.UseNumber()
	var stack []*scanFrame
	// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
	pendingNode := storedStateSchema
	pendingPath := "state"

	// 一个值消费完毕：推进父帧的键/值位置或数组下标。
	finishValue := func() {
		top := peekFrame(stack)
		if top == nil || top.opaque {
			return
		}
		if top.isArray {
			top.index++
		} else {
			top.atValue = false
		}
	}

	for {
		tok, err := dec.Token()
		if err == io.EOF {
			if len(stack) != 0 {
				return errors.New("unterminated object or array")
			}
			return nil
		}
		if err != nil {
			return err
		}

		if top := peekFrame(stack); top != nil && top.opaque {
			// 不透明容器内不做字段检查，只配对括号。
			if d, ok := tok.(json.Delim); ok {
				if d == '{' || d == '[' {
					stack = append(stack, &scanFrame{opaque: true})
				} else {
					stack = stack[:len(stack)-1]
					finishValue()
				}
			}
			continue
		}

		if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
			// 对象帧的键位置：闭括号或下一个键。
			if d, ok := tok.(json.Delim); ok {
				if d != '}' {
					return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
				}
				stack = stack[:len(stack)-1]
				finishValue()
				continue
			}
			key, ok := tok.(string)
			if !ok {
				return errors.New("object key must be a string")
			}
			if top.seen[key] {
				return fmt.Errorf("duplicate key %q at %s", key, top.path)
			}
			top.seen[key] = true
			top.atValue = true
			switch top.node.kind {
			case kindObject:
				child, known := top.node.fields[key]
				if !known {
					return fmt.Errorf("unknown field %q at %s", key, top.path)
				}
				pendingNode = child
				pendingPath = top.path + "." + key
			case kindMap:
				// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
				pendingNode = top.node.elem
				pendingPath = top.path + "[" + strconv.Quote(key) + "]"
			}
			continue
		}

		// 值位置：对象键之后的值或数组元素。
		node := pendingNode
		path := pendingPath
		if top := peekFrame(stack); top != nil && top.isArray {
			node = top.node.elem
			path = top.path + "[" + strconv.Itoa(top.index) + "]"
		}
		if d, ok := tok.(json.Delim); ok {
			switch d {
			case '{', '[':
				frame := &scanFrame{isArray: d == '[', path: path}
				shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
					(d == '[' && node.kind == kindArray)
				if !shapeOK {
					// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
					frame.opaque = true
				} else {
					frame.node = node
					if d == '{' {
						frame.seen = map[string]bool{}
					}
				}
				stack = append(stack, frame)
			default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
				if len(stack) == 0 {
					return errors.New("unexpected closing delimiter")
				}
				stack = stack[:len(stack)-1]
				finishValue()
			}
			continue
		}
		// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
		// null 不允许用来顶替字符串/布尔/整数。
		if err := checkLeafScalar(node, path, tok); err != nil {
			return err
		}
		finishValue()
	}
}

// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
func leafKindName(k schemaKind) string {
	switch k {
	case kindString:
		return "string"
	case kindBoolean:
		return "boolean"
	case kindInteger:
		return "integer"
	default:
		return "value"
	}
}

// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
func tokenKindName(tok json.Token) string {
	switch v := tok.(type) {
	case nil:
		return "null"
	case string:
		return "string"
	case bool:
		return "boolean"
	case json.Number:
		if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
			return "integer"
		}
		return "number"
	default:
		return "value"
	}
}

// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
	switch node.kind {
	case kindString, kindBoolean, kindInteger:
	default:
		return nil
	}
	if node.kind == kindInteger {
		if n, ok := tok.(json.Number); ok {
			if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
				return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
			}
			return nil
		}
	}
	want := leafKindName(node.kind)
	if got := tokenKindName(tok); got != want {
		return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
	}
	return nil
}

package govflow

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// 本文件是状态文件中“必填标量字段”的统一读取与判定。
//
// 逐票明细（representative/weight/support/voted_at）、首次计票结果
// （for_weight/against_weight）与执行凭据（executed_at/order、逐笔动作的
// index）遵循同一条字段规则：字段必须明确写出、不得为 null、JSON 类型必须与
// 声明一致（整数另要求 int64 范围内的整数字面量，小数/指数/超界同样拒绝）。
// 缺失或 null 绝不补成零值：明确写出的 false 是有效反对票，窗口允许时明确
// 写出的 0 是有效时间、权重或顺序编号。
//
// 各类记录共用这里的判定，又各自把字段名与原因短语格式化为带业务位置
// （提案编号、票据下标、计票记录标识）的错误，不会退化成没有记录位置的
// 通用错误。

// scalarKind 是必填标量字段期望的 JSON 类型；其字符串形式与错误信息中
// “want %s”的用词逐字一致。
type scalarKind string

const (
	scalarString  scalarKind = "string"
	scalarBoolean scalarKind = "boolean"
	scalarInteger scalarKind = "integer" // int64 范围内的整数字面量
)

// rawField 把一个必填标量字段的字段名、期望类型与解码时接住的原始 JSON
// 放在一起，供 validateRawFields 按声明顺序逐字段判定。
type rawField struct {
	name string
	kind scalarKind
	raw  json.RawMessage
}

// validateRawFields 按声明顺序判定各必填字段，返回第一个不合要求字段的错误；
// 字段全部合法时返回 nil。locate 把字段名与原因短语格式化为带业务位置的错误，
// 判定顺序因此完全由 fields 的声明顺序决定，与记录类型无关。
func validateRawFields(fields []rawField, locate func(field, problem string) error) error {
	for _, f := range fields {
		if problem := requiredScalarProblem(f.raw, f.kind); problem != "" {
			return locate(f.name, problem)
		}
	}
	return nil
}

// requiredScalarProblem 统一判定一个必填标量字段的原始 JSON：
// 字段未写出、显式为 null 或 JSON 类型不符都返回具体原因短语；
// 合法（含明确写出的 false 与 0）返回空串。
func requiredScalarProblem(raw json.RawMessage, kind scalarKind) string {
	switch {
	case raw == nil:
		return "is missing"
	case string(raw) == "null":
		return "is null"
	case !scalarTypeMatches(raw, kind):
		return fmt.Sprintf("has wrong type: want %s, got %s", kind, jsonValueType(raw))
	}
	return ""
}

// scalarTypeMatches 判定原始 JSON 是否确实是期望类型的值。
func scalarTypeMatches(raw json.RawMessage, kind scalarKind) bool {
	switch kind {
	case scalarString:
		return jsonValueType(raw) == "string"
	case scalarBoolean:
		return jsonValueType(raw) == "boolean"
	case scalarInteger:
		return isInt64Number(raw)
	}
	return false
}

// fillString 仅在原始 JSON 确实是字符串时把值解进 dst；否则 dst 保持零值，
// 类型不符留待校验拒绝，绝不能让错误类型悄悄落成零值并参与查询或计票。
func fillString(raw json.RawMessage, dst *string) {
	if jsonValueType(raw) == "string" {
		_ = json.Unmarshal(raw, dst)
	}
}

// fillBool 与 fillString 同理，目标类型为布尔值。
func fillBool(raw json.RawMessage, dst *bool) {
	if jsonValueType(raw) == "boolean" {
		_ = json.Unmarshal(raw, dst)
	}
}

// fillInt64 与 fillString 同理，目标类型为 int64 整数。
func fillInt64(raw json.RawMessage, dst *int64) {
	if isInt64Number(raw) {
		_ = json.Unmarshal(raw, dst)
	}
}

// jsonValueType 按字段实际写出 JSON 的首字节归类其 JSON 类型。
// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
// 字符串/布尔/null/数字/数组/对象，无需再次解码。
func jsonValueType(raw json.RawMessage) string {
	for _, c := range raw {
		switch c {
		case ' ', '\t', '\n', '\r':
			continue
		case '"':
			return "string"
		case 't', 'f':
			return "boolean"
		case 'n':
			return "null"
		case '[':
			return "array"
		case '{':
			return "object"
		default:
			return "number"
		}
	}
	return "invalid json"
}

// isInt64Number 判断原始 JSON 是否为落在有符号 64 位整数范围内的整数字面量：
// 必须是 JSON 数字（首字节为数字或 '-'），且能被 ParseInt 以 10 进制精确解析。
// 小数、指数、超界整数均返回 false。
func isInt64Number(raw json.RawMessage) bool {
	if jsonValueType(raw) != "number" {
		return false
	}
	_, err := strconv.ParseInt(strings.TrimSpace(string(raw)), 10, 64)
	return err == nil
}

package govflow

import (
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"unicode/utf8"
)

// 投票提案相关错误。
var (
	// ErrInvalidProposal：创建投票提案的参数非法（编号/成员/权重/时间/委托等）。
	ErrInvalidProposal = errors.New("invalid voting proposal")
	// ErrProposalNotFound 见 store.go。
	// ErrProposalConflict：同编号提案已存在但内容或来源不同，或重复投票选择不同。
	// ErrVoteRejected：投票被拒绝（时间窗口外、投票人无资格等）。
	ErrVoteRejected = errors.New("vote rejected")
	// ErrTallyRejected：计票被拒绝（截止时刻未到）。
	ErrTallyRejected = errors.New("tally rejected")
)

// ---- 输入与对外视图 ----

// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
type VoteMember struct {
	ID     string `json:"id"`
	Weight int64  `json:"weight"`
}

// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
// 最终未再委托的人代表沿途所有成员投票。
type Delegation struct {
	From string `json:"from"`
	To   string `json:"to"`
}

// CreateVoteInput 是创建一项投票提案的完整输入。
type CreateVoteInput struct {
	ID          string
	Members     []VoteMember
	Delegations []Delegation
	Quorum      int64
	StartAt     int64
	Deadline    int64
	TimelockEnd int64
	Actions     []string
}

// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
type MemberView struct {
	ID       string   `json:"id"`
	Weight   int64    `json:"weight"`
	Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
	Delegate string   `json:"delegate"`  // 最终代表
	Direct   string   `json:"direct_to"` // 直接委托对象；未委托为空串
}

// BallotView 是查询时展示的一张已投出的票。
type BallotView struct {
	Representative string `json:"representative"`
	Weight         int64  `json:"weight"`
	Support        bool   `json:"support"`
	VotedAt        int64  `json:"voted_at"`
}

// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
type TallyResultView struct {
	ForWeight     int64 `json:"for_weight"`
	AgainstWeight int64 `json:"against_weight"`
	Turnout       int64 `json:"turnout"`
	Quorum        int64 `json:"quorum"`
	Passed        bool  `json:"passed"`
	TalliedAt     int64 `json:"tallied_at"`
}

// VoteProposalView 是一项投票提案的完整对外视图。
type VoteProposalView struct {
	ID          string           `json:"id"`
	Source      string           `json:"source"` // vote
	State       string           `json:"state"`  // voting / passed / rejected / executed
	Quorum      int64            `json:"quorum"`
	StartAt     int64            `json:"start_at"`
	Deadline    int64            `json:"deadline"`
	TimelockEnd int64            `json:"timelock_end"`
	Actions     []string         `json:"actions"`
	TotalWeight int64            `json:"total_weight"`
	Members     []MemberView     `json:"members"`
	Ballots     []BallotView     `json:"ballots"`
	Tally       *TallyResultView `json:"tally,omitempty"`
}

// ---- 磁盘结构（JSON，版本仍为 1） ----

type storedMember struct {
	ID     string `json:"id"`
	Weight int64  `json:"weight"`
}

type storedDelegation struct {
	From string `json:"from"`
	To   string `json:"to"`
}

// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
// voted_at 不得被当作 0（首次投票时间）。
//
// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
type storedBallot struct {
	Representative string `json:"representative"`
	Weight         int64  `json:"weight"`
	Support        bool   `json:"support"`
	VotedAt        int64  `json:"voted_at"`

	representativeRaw json.RawMessage
	weightRaw         json.RawMessage
	supportRaw        json.RawMessage
	votedAtRaw        json.RawMessage
}

// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
type ballotJSONShape struct {
	Representative json.RawMessage `json:"representative"`
	Weight         json.RawMessage `json:"weight"`
	Support        json.RawMessage `json:"support"`
	VotedAt        json.RawMessage `json:"voted_at"`
}

// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
func (b *storedBallot) UnmarshalJSON(data []byte) error {
	var shape ballotJSONShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return err
	}
	b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
	b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
	// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
	// 绝不能让错误类型悄悄落成零值并参与查询或计票。
	fillString(shape.Representative, &b.Representative)
	fillInt64(shape.Weight, &b.Weight)
	fillBool(shape.Support, &b.Support)
	fillInt64(shape.VotedAt, &b.VotedAt)
	return nil
}

// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
func (b storedBallot) MarshalJSON() ([]byte, error) {
	return json.Marshal(storedBallotOut{
		Representative: b.Representative,
		Weight:         b.Weight,
		Support:        b.Support,
		VotedAt:        b.VotedAt,
	})
}

// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
type storedBallotOut struct {
	Representative string `json:"representative"`
	Weight         int64  `json:"weight"`
	Support        bool   `json:"support"`
	VotedAt        int64  `json:"voted_at"`
}

// mustStoreBallot 构造一张内存中的合法票据（投票成功路径使用）。
// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
// validateStoredBallot 判定时不会把本进程新建的票据误判为字段缺失。
func mustStoreBallot(representative string, weight int64, support bool, votedAt int64) storedBallot {
	repRaw, _ := json.Marshal(representative)
	wRaw, _ := json.Marshal(weight)
	supRaw, _ := json.Marshal(support)
	atRaw, _ := json.Marshal(votedAt)
	return storedBallot{
		Representative:    representative,
		Weight:            weight,
		Support:           support,
		VotedAt:           votedAt,
		representativeRaw: repRaw,
		weightRaw:         wRaw,
		supportRaw:        supRaw,
		votedAtRaw:        atRaw,
	}
}

// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
// “缺失/空值/类型不符”的判定与计票结果、执行凭据共用同一份规则
// （validateRawFields），此处只补充票据的业务位置：提案编号 + 票据下标。
func validateStoredBallot(id string, index int, b *storedBallot) error {
	return validateRawFields([]rawField{
		{name: "representative", kind: scalarString, raw: b.representativeRaw},
		{name: "weight", kind: scalarInteger, raw: b.weightRaw},
		{name: "support", kind: scalarBoolean, raw: b.supportRaw},
		{name: "voted_at", kind: scalarInteger, raw: b.votedAtRaw},
	}, func(field, problem string) error {
		return fmt.Errorf("voting proposal %q ballot %d field %q %s", id, index, field, problem)
	})
}

// storedTally 是已保存的首次计票结果。只要提案有计票结果，for_weight 与
// against_weight 就必须各自明确写出：即使某一侧（或两侧）的实际票重为零，
// 也不得靠零值/默认值补出治理记录——缺失或 null 的 for_weight 不得被当作 0
// 赞成，缺失或 null 的 against_weight 不得被当作 0 反对。
//
// 两个权重字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
// 仍可区分：encoding/json 直接解进 int64 时会把这三种情况都折叠成 0，恰好与
// “该侧没有票”的合法零权重无法区分。每个字段的“缺失/空值/类型不符”由
// validateStoredTally 判定。
type storedTally struct {
	ForWeight     int64 `json:"for_weight"`
	AgainstWeight int64 `json:"against_weight"`
	TalliedAt     int64 `json:"tallied_at"`

	forWeightRaw     json.RawMessage
	againstWeightRaw json.RawMessage
}

// tallyJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
type tallyJSONShape struct {
	ForWeight     json.RawMessage `json:"for_weight"`
	AgainstWeight json.RawMessage `json:"against_weight"`
	TalliedAt     int64           `json:"tallied_at"`
}

// UnmarshalJSON 保留两个权重字段是否出现及其原始写法（缺失为 nil、null 为
// "null"），供 validateStoredTally 区分缺失、空值与类型不符。单个字段类型不符时
// 这里不返回错误（对应治理字段保持零值），以免解码器在不含提案编号的通用错误处
// 提前失败；定位与判定统一交给 validateStoredTally。
func (t *storedTally) UnmarshalJSON(data []byte) error {
	var shape tallyJSONShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return err
	}
	t.forWeightRaw, t.againstWeightRaw = shape.ForWeight, shape.AgainstWeight
	t.TalliedAt = shape.TalliedAt
	// 仅当字段确实是 int64 整数时才填充治理字段；类型不符留待校验拒绝，
	// 绝不能让错误类型悄悄落成 0 并参与查询或再次计票。
	fillInt64(shape.ForWeight, &t.ForWeight)
	fillInt64(shape.AgainstWeight, &t.AgainstWeight)
	return nil
}

// mustStoreTally 构造一份内存中的合法计票结果（首次计票路径使用）。
// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
// validateStoredTally 判定时不会把本进程新建的计票结果误判为字段缺失。
func mustStoreTally(forWeight, againstWeight, talliedAt int64) *storedTally {
	forRaw, _ := json.Marshal(forWeight)
	againstRaw, _ := json.Marshal(againstWeight)
	return &storedTally{
		ForWeight:        forWeight,
		AgainstWeight:    againstWeight,
		TalliedAt:        talliedAt,
		forWeightRaw:     forRaw,
		againstWeightRaw: againstRaw,
	}
}

// validateStoredTally 严格判定一份已保存计票结果的两个权重字段：
// for_weight 与 against_weight 任一未写出、显式为 null 或不是 int64 整数
// （字符串/小数/指数/超界）都返回带提案编号、字段名与原因的错误。
// 明确写出的 0 是合法权重（该侧没有票），不得当成缺失。
// “缺失/空值/类型不符”的判定与逐票明细、执行凭据共用同一份规则
// （validateRawFields），此处只补充计票记录的业务位置：提案编号 + tally 标识。
func validateStoredTally(id string, t *storedTally) error {
	return validateRawFields([]rawField{
		{name: "for_weight", kind: scalarInteger, raw: t.forWeightRaw},
		{name: "against_weight", kind: scalarInteger, raw: t.againstWeightRaw},
	}, func(field, problem string) error {
		return fmt.Errorf("voting proposal %q tally field %q %s", id, field, problem)
	})
}

// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
// 动作文本与顺序原样保存（顺序影响相等性）。
type storedVoteProposal struct {
	ID          string             `json:"id"`
	State       string             `json:"state"`
	Members     []storedMember     `json:"members"`
	Delegations []storedDelegation `json:"delegations"`
	Quorum      int64              `json:"quorum"`
	StartAt     int64              `json:"start_at"`
	Deadline    int64              `json:"deadline"`
	TimelockEnd int64              `json:"timelock_end"`
	Actions     []string           `json:"actions"`
	Ballots     []storedBallot     `json:"ballots"`
	Tally       *storedTally       `json:"tally,omitempty"`
}

// ---- 校验与派生 ----

type proposalSpec struct {
	members  []VoteMember
	weights  map[string]int64
	delegate map[string]string // 直接委托对象
	pathOf   map[string][]string
	headOf   map[string]string // 最终代表
	groupW   map[string]int64  // 最终代表名下归集的全部原始权重
	total    int64
}

// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
// 任何非法条件都返回错误，调用方必须整项拒绝。
//
// 提案编号、成员编号与动作原文还必须是合法 UTF-8：状态文件以 JSON 保存，
// encoding/json 会把字符串中的非法 UTF-8 字节悄悄改写成替换字符 U+FFFD
// 且不报错。创建入口若放行，落盘的编号就不再是用户提交的原文——原编号
// 无法查询，不同成员可能被改写成同一个名字，整份状态文件随之无法读取。
// 因此这三类文本在一切落盘之前逐字校验，非法输入整项创建失败；
// 合法文本（含中文、表情、用户明确写出的 U+FFFD，以及 "\uD800" 这类
// 由反斜杠与普通字母组成的字面文本——创建参数不是 JSON 字符串，不做
// 转义重解释）原样保留。
func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
	if in.ID == "" {
		return nil, invalidProposal("proposal id must not be empty")
	}
	if problem := invalidUTF8(in.ID); problem != "" {
		return nil, invalidProposal("proposal id is not valid UTF-8: %s", problem)
	}
	if len(in.Members) == 0 {
		return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
	}
	weights := make(map[string]int64, len(in.Members))
	order := make([]string, 0, len(in.Members))
	for i, m := range in.Members {
		if m.ID == "" {
			return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
		}
		if problem := invalidUTF8(m.ID); problem != "" {
			return nil, invalidProposal("proposal %s: member %d id is not valid UTF-8: %s", in.ID, i, problem)
		}
		if _, dup := weights[m.ID]; dup {
			return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
		}
		if m.Weight <= 0 {
			return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
		}
		weights[m.ID] = m.Weight
		order = append(order, m.ID)
	}

	// 总权重必须在 int64 范围内（各权重已为正）。
	var total int64
	for _, m := range in.Members {
		sum, ok := addInt64(total, m.Weight)
		if !ok {
			return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
		}
		total = sum
	}

	if in.Quorum < 1 || in.Quorum > total {
		return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
	}
	if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
		return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
			in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
	}

	// 动作原文逐字校验编码，但不校验动作格式：编码合法而格式错误的动作
	// 照常创建，由执行操作按现有规则拒绝，创建入口不提前改变动作资格。
	for i, action := range in.Actions {
		if problem := invalidUTF8(action); problem != "" {
			return nil, invalidProposal("proposal %s: action %d text is not valid UTF-8: %s", in.ID, i, problem)
		}
	}

	delegate := make(map[string]string, len(in.Delegations))
	for _, d := range in.Delegations {
		if d.From == "" || d.To == "" {
			return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
		}
		if _, ok := weights[d.From]; !ok {
			return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
		}
		if _, ok := weights[d.To]; !ok {
			return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
		}
		if d.From == d.To {
			return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
		}
		if _, dup := delegate[d.From]; dup {
			return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
		}
		delegate[d.From] = d.To
	}

	// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
	// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
	// 所以该遍历必然终止。
	// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
	// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
	// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
	pathOf := make(map[string][]string, len(weights))
	headOf := make(map[string]string, len(weights))
	for _, id := range order {
		if _, done := headOf[id]; done {
			continue
		}
		chain := []string{id}
		onChain := map[string]int{id: 0}
		cur := id
		for {
			next, has := delegate[cur]
			if !has {
				break // cur 即未再委托的最终代表
			}
			if pos, cyc := onChain[next]; cyc {
				return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
			}
			if resolved, ok := pathOf[next]; ok {
				// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
				chain = append(chain, resolved...)
				cur = resolved[len(resolved)-1]
				break
			}
			chain = append(chain, next)
			onChain[next] = len(chain) - 1
			cur = next
		}
		head := cur
		// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
		// 后缀成员均已登记，这里只补齐尚未解析的成员。
		for i := 0; i < len(chain); i++ {
			member := chain[i]
			if _, ok := headOf[member]; !ok {
				pathOf[member] = append([]string(nil), chain[i:]...)
				headOf[member] = head
			}
		}
	}

	// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
	groupW := make(map[string]int64)
	for _, id := range order {
		head := headOf[id]
		sum, ok := addInt64(groupW[head], weights[id])
		if !ok {
			return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
		}
		groupW[head] = sum
	}

	return &proposalSpec{
		members:  append([]VoteMember(nil), in.Members...),
		weights:  weights,
		delegate: delegate,
		pathOf:   pathOf,
		headOf:   headOf,
		groupW:   groupW,
		total:    total,
	}, nil
}

func invalidProposal(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
}

// invalidUTF8 定位文本中第一个非法 UTF-8 字节并给出可读描述；文本合法时
// 返回空串。残缺的多字节序列、续字节缺失、越界编码以及 WTF-8 形式写出的
// 代理码位（如 ED A0 80）都会被 DecodeRuneInString 判为单字节 RuneError；
// 用户明确写出的合法 U+FFFD（EF BF BD）解码长度为 3，照常放行。
func invalidUTF8(s string) string {
	for i := 0; i < len(s); {
		c := s[i]
		if c < utf8.RuneSelf {
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			return fmt.Sprintf("illegal byte 0x%02X at byte offset %d", c, i)
		}
		i += size
	}
	return ""
}

// proposalsEqual 判断重试内容是否与已存提案逐项相同。
// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
	if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
		stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
		return false
	}
	if !sameActions(stored.Actions, in.Actions) {
		return false
	}
	if len(stored.Members) != len(in.Members) {
		return false
	}
	for _, m := range stored.Members {
		if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
			return false
		}
	}
	if len(stored.Delegations) != len(in.Delegations) {
		return false
	}
	for _, d := range stored.Delegations {
		to, ok := spec.delegate[d.From]
		if !ok || to != d.To {
			return false
		}
	}
	return true
}

// ---- 存储操作 ----

// CreateVoteProposal 创建一项投票提案。
// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
// 非法条件整项拒绝，不落盘任何部分变化。提案编号、成员编号与动作原文
// 含有非法 UTF-8 字节时同样整项拒绝（ErrInvalidProposal）：保存会把这些
// 字节改写成 U+FFFD，使落盘文本不再是用户提交的原文；因此即使非法输入
// 改写后恰好等于状态中已存在的合法编号（如含真实 U+FFFD 的编号），
// 也不被当作该编号的重试或覆盖。合法文本逐字保留，不做任何转义重解释。
func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
	spec, err := validateProposalInput(in)
	if err != nil {
		return nil, false, err
	}
	commit, err := s.begin()
	if err != nil {
		return nil, false, err
	}
	defer commit()

	state, err := s.loadLocked()
	if err != nil {
		return nil, false, err
	}
	if existing, ok := state.VoteProposals[in.ID]; ok {
		if !proposalsEqual(existing, in, spec) {
			return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
		}
		v := voteProposalView(existing)
		return v, true, nil
	}
	if _, ok := state.Proposals[in.ID]; ok {
		// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
		return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
	}

	stored := &storedVoteProposal{
		ID:          in.ID,
		State:       "voting",
		Members:     make([]storedMember, 0, len(in.Members)),
		Delegations: make([]storedDelegation, 0, len(in.Delegations)),
		Quorum:      in.Quorum,
		StartAt:     in.StartAt,
		Deadline:    in.Deadline,
		TimelockEnd: in.TimelockEnd,
		Actions:     copyActions(in.Actions),
		Ballots:     []storedBallot{},
	}
	for _, m := range in.Members {
		stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
	}
	for _, d := range in.Delegations {
		stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
	}
	state.VoteProposals[in.ID] = stored
	if err := s.commitLocked(state); err != nil {
		return nil, false, err
	}
	return voteProposalView(stored), false, nil
}

func voteReject(reason string) error {
	return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
}

func tallyReject(reason string) error {
	return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
}

// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----

// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
type ballotCounts struct {
	forWeight     int64
	againstWeight int64
}

// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
func (c ballotCounts) turnout() (int64, bool) {
	return addInt64(c.forWeight, c.againstWeight)
}

// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
func votePasses(forWeight, againstWeight, quorum int64) bool {
	if forWeight <= againstWeight {
		return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
	}
	return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
}

// tallyVerdict 把通过条件映射为提案首次计票后的状态。
func tallyVerdict(passed bool) string {
	if passed {
		return "passed"
	}
	return "rejected"
}

// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
func countBallots(ballots []storedBallot) (ballotCounts, error) {
	var c ballotCounts
	for _, b := range ballots {
		if b.Support {
			sum, ok := addInt64(c.forWeight, b.Weight)
			if !ok {
				return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
			}
			c.forWeight = sum
		} else {
			sum, ok := addInt64(c.againstWeight, b.Weight)
			if !ok {
				return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
			}
			c.againstWeight = sum
		}
	}
	return c, nil
}

// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
	seen := map[string]bool{}
	for i, b := range ballots {
		if b.Representative == "" {
			return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
		}
		if spec.headOf[b.Representative] != b.Representative {
			return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
				id, i, b.Representative)
		}
		if seen[b.Representative] {
			return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
		}
		seen[b.Representative] = true
		if b.Weight != spec.groupW[b.Representative] {
			return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
				id, b.Representative, b.Weight, spec.groupW[b.Representative])
		}
	}
	counts, err := countBallots(ballots)
	if err != nil {
		return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
	}
	return counts, nil
}

// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
	if voter == "" {
		return nil, voteReject("voter id must not be empty")
	}
	commit, err := s.begin()
	if err != nil {
		return nil, err
	}
	defer commit()

	state, err := s.loadLocked()
	if err != nil {
		return nil, err
	}
	p, ok := state.VoteProposals[id]
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
	}
	spec, verr := specOf(p)
	if verr != nil {
		return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
	}
	if _, member := spec.weights[voter]; !member {
		return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
	}
	if spec.headOf[voter] != voter {
		return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
	}
	// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
	// 改投另一选择报冲突，绝不静默覆盖。
	for i := range p.Ballots {
		if p.Ballots[i].Representative == voter {
			if p.Ballots[i].Support != support {
				return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
					ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
			}
			b := p.Ballots[i]
			return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
		}
	}
	if p.Tally != nil {
		return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
	}
	if now < p.StartAt || now >= p.Deadline {
		return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
	}

	p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
	if err := s.commitLocked(state); err != nil {
		return nil, err
	}
	return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
}

func voteChoice(support bool) string {
	if support {
		return "for"
	}
	return "against"
}

// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
// 且赞成严格多于反对才通过。未投权重不计入参与量。
// 计票只确定状态，不转账；再次计票始终返回首次结论。
func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
	commit, err := s.begin()
	if err != nil {
		return nil, err
	}
	defer commit()

	state, err := s.loadLocked()
	if err != nil {
		return nil, err
	}
	p, ok := state.VoteProposals[id]
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
	}
	if p.Tally != nil {
		return storedTallyResult(p), nil
	}
	if now < p.Deadline {
		return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
	}

	spec, verr := specOf(p)
	if verr != nil {
		return nil, verr
	}
	// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
	// 同时用于首次计票、打开文件时的重放校验与查询结论。
	counts, verr := verifyBallots(id, p.Ballots, spec)
	if verr != nil {
		return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
	}
	passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
	p.Tally = mustStoreTally(counts.forWeight, counts.againstWeight, now)
	p.State = tallyVerdict(passed)
	if err := s.commitLocked(state); err != nil {
		return nil, err
	}
	return storedTallyResult(p), nil
}

// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
func storedTallyResult(p *storedVoteProposal) *TallyResultView {
	if p.Tally == nil {
		return nil
	}
	c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
	turnout, _ := c.turnout()
	return &TallyResultView{
		ForWeight:     c.forWeight,
		AgainstWeight: c.againstWeight,
		Turnout:       turnout,
		Quorum:        p.Quorum,
		Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
		TalliedAt:     p.Tally.TalliedAt,
	}
}

// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
	state, err := s.readState()
	if err != nil {
		return nil, false, err
	}
	p, ok := state.VoteProposals[id]
	if !ok {
		return nil, false, nil
	}
	return voteProposalView(p), true, nil
}

// VoteProposals 返回全部投票提案，按编号排序。
func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
	state, err := s.readState()
	if err != nil {
		return nil, err
	}
	return voteProposalViews(state), nil
}

func voteProposalViews(state *storedState) []*VoteProposalView {
	out := make([]*VoteProposalView, 0, len(state.VoteProposals))
	for _, p := range state.VoteProposals {
		out = append(out, voteProposalView(p))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func voteProposalView(p *storedVoteProposal) *VoteProposalView {
	spec, err := specOf(p)
	if err != nil {
		// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
		panic("govflow: building view of corrupt proposal: " + err.Error())
	}
	members := make([]MemberView, 0, len(p.Members))
	for _, m := range p.Members { // 保持成员提交顺序
		mv := MemberView{
			ID:       m.ID,
			Weight:   m.Weight,
			Path:     append([]string(nil), spec.pathOf[m.ID]...),
			Delegate: spec.headOf[m.ID],
		}
		if to, ok := spec.delegate[m.ID]; ok {
			mv.Direct = to
		}
		members = append(members, mv)
	}
	ballots := make([]BallotView, 0, len(p.Ballots))
	for _, b := range p.Ballots { // 保持首次投票先后顺序
		ballots = append(ballots, BallotView{
			Representative: b.Representative,
			Weight:         b.Weight,
			Support:        b.Support,
			VotedAt:        b.VotedAt,
		})
	}
	v := &VoteProposalView{
		ID:          p.ID,
		Source:      "vote",
		State:       p.State,
		Quorum:      p.Quorum,
		StartAt:     p.StartAt,
		Deadline:    p.Deadline,
		TimelockEnd: p.TimelockEnd,
		Actions:     copyActions(p.Actions),
		TotalWeight: spec.total,
		Members:     members,
		Ballots:     ballots,
	}
	if p.Tally != nil {
		v.Tally = storedTallyResult(p)
	}
	return v
}

// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
func specOf(p *storedVoteProposal) (*proposalSpec, error) {
	in := &CreateVoteInput{
		ID:          p.ID,
		Quorum:      p.Quorum,
		StartAt:     p.StartAt,
		Deadline:    p.Deadline,
		TimelockEnd: p.TimelockEnd,
		Actions:     p.Actions,
	}
	in.Members = make([]VoteMember, len(p.Members))
	for i, m := range p.Members {
		in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
	}
	in.Delegations = make([]Delegation, len(p.Delegations))
	for i, d := range p.Delegations {
		in.Delegations[i] = Delegation{From: d.From, To: d.To}
	}
	return validateProposalInput(in)
}

// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
func validateVoteProposals(state *storedState) error {
	for key, p := range state.VoteProposals {
		if p == nil {
			return fmt.Errorf("voting proposal %q is empty", key)
		}
		if p.ID != key || p.ID == "" {
			return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
		}
		if _, collide := state.Proposals[p.ID]; collide {
			return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
		}
		switch p.State {
		case "voting", "passed", "rejected", "executed":
		default:
			return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
		}
		spec, err := specOf(p)
		if err != nil {
			return err
		}

		// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
		// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
		// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
		// 默认成 0 后再继续给出查询或计票的部分结果。
		for i := range p.Ballots {
			if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
				return err
			}
		}

		// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
		// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
		// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
		counts, err := verifyBallots(p.ID, p.Ballots, spec)
		if err != nil {
			return err
		}
		// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
		// 仍只属于打开时的明细校验。
		for _, b := range p.Ballots {
			if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
				return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
					p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
			}
		}

		switch {
		case p.Tally == nil:
			if p.State != "voting" {
				return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
			}
		default:
			if p.State == "voting" {
				return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
			}
			// 只要提案有计票结果，for_weight 与 against_weight 就必须各自明确
			// 写出且为 int64 整数。先于权重重放核对执行：字段缺损时直接判整份
			// 文件损坏，绝不能把缺失的一侧默认补成 0（恰好等于该侧真实零票重）
			// 后再继续给出查询或再次计票的结果。明确写出的 0 是合法权重。
			if err := validateStoredTally(p.ID, p.Tally); err != nil {
				return err
			}
			if p.Tally.TalliedAt < p.Deadline {
				return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
			}
			if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
				return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
					p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
			}
			// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
			// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
			passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
			if passedNow != (p.State == "passed" || p.State == "executed") {
				return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
			}
		}
	}
	return nil
}

