542	func runProposal(args []string) {
543		cf := newCmdFlags("proposal")
544		id := cf.fs.String("id", "", "proposal id")
545		cf.parse(args)
546		if *id == "" {
547			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
548			os.Exit(2)
549		}
550		store, err := govflow.Open(cf.state)
551		if err != nil {
552			fail(err)
553		}
554		defer store.Close()
555		record, ok, err := store.Proposal(*id)
556		if err != nil {
557			fail(err)
558		}
559		if ok {
560			// 保持既有 JSON 形状：直接输出登记提案记录。
561			if cf.asJSON {
562				emitJSON(record)
563				return
564			}
565			printProposalText(record)
566			return
567		}
568		voteView, vok, verr := store.VoteProposal(*id)
569		if verr != nil {
570			fail(verr)
571		}
572		if !vok {
573			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
574		}
575		if cf.asJSON {
576			emitJSON(voteView)
577			return
578		}
579		printVoteProposalText(voteView)
580	}
