666	func printProposalText(p govflow.ProposalRecord) {
667		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
668		for i, action := range p.Actions {
669			fmt.Printf("  action %d: %s\n", i, action)
670		}
671	}
672	
673	func printVoteProposalText(v *govflow.VoteProposalView) {
674		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
675			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
676		for _, m := range v.Members {
677			chain := strings.Join(m.Path, "->")
678			if len(m.Path) == 1 {
679				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
680			} else {
681				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
682			}
683		}
684		for i, action := range v.Actions {
685			fmt.Printf("  action %d: %s\n", i, action)
686		}
687		for _, b := range v.Ballots {
688			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
689				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
690		}
691		if v.Tally != nil {
692			verdict := "rejected"
693			if v.Tally.Passed {
694				verdict = "passed"
695			}
696			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
697				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
698		}
699	}
700	
701	func printReceiptText(r *govflow.Receipt, header bool) {
702		if header {
703			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
704		} else {
705			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
706		}
707		for _, ar := range r.Actions {
708			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
709			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
710			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
711		}
712	}
713	
714	func runDemo() {
715		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
716			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
717		if err := govflow.Vote(&proposal, 700, true); err != nil {
718			fmt.Println("vote refused:", err)
719		}
720		if err := govflow.Vote(&proposal, 200, false); err != nil {
721			fmt.Println("vote refused:", err)
722		}
723		next := govflow.Tally(&proposal)
724		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
725		proposal.State = next
726		proposal.TimelockEnd = 400
727		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
728	}
