	store, err := govflow.Open(cf.state)
	if err != nil {
		fail(err)
	}
	defer store.Close()
	// 响应字段一律取这次登记实际认可的记录：首次登记为 passed；相同内容重试
	// 保留已有记录的实际状态（passed 或 executed），已执行的提案不得报成 passed。
	record, existed, err := store.RegisterProposal(*id, timelock, []string(actions))
	if err != nil {
